1:#include "runner/hack_runner.h"
2:
3:#include <stdlib.h>
4:
5:#include "hacks/registry.h"
6:#include "screenhackI.h"
7:#include "x11shim/xshim.h"
8:
9:struct HackRunner {
10:  Canvas *canvas;
11:  Display *dpy;
12:  const HackEntry *const *hacks;
13:  int count;
14:  int index;
15:  void *closure;
16:  int running;
17:};
18:
19:HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
20:                               int count) {
21:  HackRunner *r = (HackRunner *)calloc(1, sizeof(*r));
22:  if (!r) return NULL;
23:  r->canvas = canvas;
24:  r->dpy = xshim_open_display(canvas);
25:  r->hacks = hacks;
26:  r->count = count;
27:  if (!r->dpy) {
28:    free(r);
29:    return NULL;
30:  }
31:  return r;
32:}
33:
34:HackRunner *runner_create(Canvas *canvas) {
35:  return runner_create_with(canvas, g_hacks, g_hack_count);
36:}
37:
38:typedef struct {
39:  const char *const *defaults;
40:  void *(*init)(Display *, Window);
41:  unsigned long (*draw)(Display *, Window, void *);
42:  void (*free)(Display *, Window, void *);
43:  void *setup_arg; /* xlockmore_init's hidden third argument; NULL otherwise */
44:  int has_setup_arg;
45:} Callbacks;
46:
47:/* An xlockmore hack's table is empty until its setup_cb has run, and that
48: * allocates, so run it once rather than on every button press. */
49:static Callbacks callbacks_for(const HackEntry *e) {
50:  struct xscreensaver_function_table *t = e->xsft;
51:  if (!t) return (Callbacks){e->defaults, e->init, e->draw, e->free, NULL, 0};
52:  if (!t->init_cb && t->setup_cb) t->setup_cb(t, t->setup_arg);
53:  return (Callbacks){t->defaults, t->init_cb, t->draw_cb, t->free_cb,
54:                     t->setup_arg, 1};
55:}
56:
57:static void stop(HackRunner *r) {
58:  if (!r->running) return;
59:  callbacks_for(r->hacks[r->index]).free(r->dpy, XSHIM_WINDOW, r->closure);
60:  /* The display outlives the hack, so release what the hack forgot to free, as
61:   * an X server does when a client disconnects. */
62:  xshim_release_pixmaps(r->dpy);
63:  r->closure = NULL;
64:  r->running = 0;
65:}
66:
67:void runner_destroy(HackRunner *r) {
68:  if (!r) return;
69:  stop(r);
70:  xshim_close_display(r->dpy);
71:  free(r);
72:}
73:
74:int runner_start(HackRunner *r, int index) {
75:  if (index < 0 || index >= r->count) return -1;
76:  stop(r);
77:  r->index = index;
78:  const Callbacks cb = callbacks_for(r->hacks[index]);
79:  xshim_set_defaults(cb.defaults);
80:  xshim_set_overrides(r->hacks[index]->overrides);
81:  canvas_clear(r->canvas, (uint16_t)xshim_background_pixel());
82:  if (cb.has_setup_arg) {
83:    /* Like screenhack.c: init_cb is declared with two arguments, but the
84:     * xlockmore one takes its function table as a third. */
85:    void *(*init3)(Display *, Window, void *) =
86:        (void *(*)(Display *, Window, void *))cb.init;
87:    r->closure = init3(r->dpy, XSHIM_WINDOW, cb.setup_arg);
88:  } else {
89:    r->closure = cb.init(r->dpy, XSHIM_WINDOW);
90:  }
91:  r->running = 1;
92:  return 0;
93:}
94:
95:unsigned long runner_step(HackRunner *r) {
96:  if (!r->running) return RUNNER_MAX_DELAY_US;
97:  unsigned long d =
98:      callbacks_for(r->hacks[r->index]).draw(r->dpy, XSHIM_WINDOW, r->closure);
99:  if (d < RUNNER_MIN_DELAY_US) return RUNNER_MIN_DELAY_US;
100:  if (d > RUNNER_MAX_DELAY_US) return RUNNER_MAX_DELAY_US;
101:  return d;
102:}
103:
104:unsigned long runner_remaining_delay_us(unsigned long requested_us,
105:                                        unsigned long spent_us) {
106:  return requested_us > spent_us ? requested_us - spent_us : 0;
107:}
108:
109:int runner_next(HackRunner *r) {
110:  runner_start(r, (r->index + 1) % r->count);
111:  return r->index;
112:}
113:
114:int runner_prev(HackRunner *r) {
115:  runner_start(r, (r->index + r->count - 1) % r->count);
116:  return r->index;
117:}
118:
119:int runner_index(const HackRunner *r) { return r->index; }

