120:#include <esp_timer.h>
121:extern "C" {
122:#include "runner/te_sync.h"
123:}
124:static const int kPinTE = 38;
125:static const uint32_t kTeSyncOffsetUs = 7400;
126:static const uint32_t kTeTimeoutUs = 100000;
127:static TeSync teSync;
128:
129:#ifdef TE_DIAG
130:/* Build with -DTE_DIAG to log, every few seconds, the TE period and where in
131: * the cycle each full push starts and flushes. */
132:static const int kTeRing = 512;
133:static volatile uint32_t teAt[kTeRing];
134:static volatile uint8_t teLevel[kTeRing];
135:static volatile uint32_t teHead;
136:static const int kPushLog = 64;
137:static uint32_t pushStart[kPushLog], pushFlush[kPushLog], pushEnd[kPushLog];
138:static int pushCount;
139:static uint32_t flushBeganUs;
140:static uint32_t teReportedHead;
141:#endif
142:
143:static void IRAM_ATTR teIsr() {
144:  const uint32_t now = (uint32_t)esp_timer_get_time();
145:  const int level = gpio_get_level((gpio_num_t)kPinTE);
146:  te_sync_edge(&teSync, now, level);
147:#ifdef TE_DIAG
148:  uint32_t i = teHead;
149:  teAt[i % kTeRing] = now;
150:  teLevel[i % kTeRing] = (uint8_t)level;
151:  teHead = i + 1;
152:#endif
153:}
154:
155:static void teInit() {
156:  te_sync_init(&teSync, kTeSyncOffsetUs, kTeTimeoutUs);
157:  pinMode(kPinTE, INPUT);
158:  attachInterrupt(kPinTE, teIsr, CHANGE);
159:}
160:
161:#ifdef TE_DIAG
162:struct TeStat {
163:  uint32_t sum, min, max;
164:  int n;
165:};
166:static void teAdd(TeStat *s, uint32_t v) {
167:  if (!s->n || v < s->min) s->min = v;
168:  if (!s->n || v > s->max) s->max = v;
169:  s->sum += v;
170:  s->n++;
171:}
172:static void teShow(const char *name, const TeStat *s) {
173:  Serial.printf(" %s mean=%u min=%u max=%u", name,
174:                s->n ? (unsigned)(s->sum / s->n) : 0u, (unsigned)s->min,
175:                (unsigned)s->max);
176:}
177:
178:/* Time since the latest rising edge at or before t, if there was one. */
179:static bool teSinceRise(const uint32_t *rise, int nr, uint32_t t, uint32_t *out) {
180:  bool found = false;
181:  for (int i = 0; i < nr; i++)
182:    if ((int32_t)(rise[i] - t) <= 0) {
183:      *out = t - rise[i];
184:      found = true;
185:    }
186:  return found;
187:}
188:
189:static void teReport() {
190:  uint32_t head = teHead;
191:  uint32_t n = head - teReportedHead;
192:  if (n > (uint32_t)kTeRing) n = kTeRing;
193:  static uint32_t rise[kTeRing];
194:  int nr = 0;
195:  TeStat period = {}, startAt = {}, flushAt = {}, flushLen = {}, copyLen = {};
196:  for (uint32_t k = head - n; k != head; k++)
197:    if (teLevel[k % kTeRing]) rise[nr++] = teAt[k % kTeRing];
198:  for (int i = 1; i < nr; i++) teAdd(&period, rise[i] - rise[i - 1]);
199:  for (int p = 0; p < pushCount; p++) {
200:    uint32_t v;
370:#endif
371:}
372:static const PushSink pushSink = {nullptr, sinkBegin, sinkRow, sinkAll, sinkEnd};
373:
374:static void present() {
375:  uint32_t now = millis();
376:  if (overlay_name_visible(&overlay, now))
377:    stampText(&namePatch, g_hacks[runner_index(runner)]->name, kSize / 2,
378:              kNameY, &fonts::DejaVu24);
379:  if (overlay_badge_visible(&overlay))
380:    stampText(&namePatch, kBadgeName, kSize / 2, kSize / 2,
381:              &fonts::Font8x8C64, kBadgeScale);
382:  if (overlay_qr_visible(&overlay) && qrPixels) stampQr(&infoPatch);
383:  if (overlay_fps_visible(&overlay) || overlay_battery_visible(&overlay)) {
384:    char text[16];
385:    if (overlay_fps_visible(&overlay))
386:      overlay_fps_text(&overlay, text, sizeof text);
387:    else
388:      overlay_battery_text(&overlay, text, sizeof text);
389:    stampText(&infoPatch, text, kSize / 2, kFpsY, &fonts::DejaVu18);
390:  }
391:  overlay_drawn(&overlay, now);
392:  if (g_hacks[runner_index(runner)]->sync_to_refresh) {
393:    /* After the overlay is stamped, so stamping does not move the start. */
394:    const uint32_t syncWaitUs =
395:        te_sync_wait_us(&teSync, (uint32_t)esp_timer_get_time());
396:    if (syncWaitUs) delayMicroseconds(syncWaitUs);
397:  }
398:#ifdef TE_DIAG
399:  uint32_t pushT0 = (uint32_t)esp_timer_get_time();
400:#endif
401:  int pushedRows = push_present(&canvas, pushRows, &pushSink);
402:  rowsPushed += pushedRows;
403:#ifdef TE_DIAG
404:  if (pushedRows > 300 && pushCount < kPushLog) {
405:    pushStart[pushCount] = pushT0;
406:    pushFlush[pushCount] = flushBeganUs;
407:    pushEnd[pushCount] = (uint32_t)esp_timer_get_time();
408:    pushCount++;
409:  }
410:#endif
411:  unstamp(&infoPatch);
412:  unstamp(&namePatch);
413:}
414:
415:/* Whatever started the hack, the name shows again, the rotation countdown
416: * restarts and the stats begin afresh. */
417:static void hackStarted() {
418:  uint32_t now = millis();
419:  overlay_hack_started(&overlay, now);
420:  rotation_reset(&rotation, now);
421:  resetStats();
422:}
423:
424:/* Returns true if a button switched hacks. */
425:static bool pollButtons() {
426:  bool switched = false;
427:  uint32_t pressedAt = 0;
428:  if (button_latch_take(&latchA, &pressedAt)) {
429:    runner_next(runner);
430:    switched = true;
431:  }
432:  if (button_latch_take(&latchB, &pressedAt)) {
433:    runner_prev(runner);
434:    switched = true;
435:  }
436:  if (switched) {
437:    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
438:                  g_hacks[runner_index(runner)]->name,
439:                  (unsigned)(millis() - pressedAt),
440:                  (unsigned)ESP.getFreeHeap(),
441:                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
442:    hackStarted();
443:  }
444:  return switched;
445:}
446:
447:/* Returns true if the timer moved on to the next hack. */
448:static bool pollRotation() {
449:  if (!rotation_due(&rotation, millis())) return false;
450:  runner_next(runner);
451:  Serial.printf("rotate -> %s heap=%u psram=%u\n",
452:                g_hacks[runner_index(runner)]->name, (unsigned)ESP.getFreeHeap(),
453:                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
454:  hackStarted();
455:  return true;
456:}
457:
458:/* A tap anywhere cycles the readout: nothing, name badge, QR code, fps,
459: * battery. Call
460: * right after M5.update(), which is the only place the touch edge is
461: * recorded. */
462:static void pollTouch() {
463:  if (M5.Touch.getDetail().wasPressed()) overlay_cycle_info(&overlay);
464:}
465:
466:/* The fuel gauge is read over I2C through the power chip, which can fail the
467: * first transaction after idle, so read it every 30 s, not every frame. A
468: * failed read is negative and the overlay keeps the last good level. */
469:static void pollBattery() {
470:  static uint32_t lastReadMs;
471:  static bool readOnce;
472:  uint32_t now = millis();
473:  if (readOnce && now - lastReadMs < kBatteryEveryMs) return;
474:  readOnce = true;
475:  lastReadMs = now;
476:  overlay_set_battery(&overlay, M5.Power.getBatteryLevel());
477:}
478:
479:void setup() {
480:  auto cfg = M5.config();
481:  M5.begin(cfg);
482:  Serial.begin(115200);
483:  M5.Display.setSwapBytes(false);
484:  teInit();
485:
486:  button_latch_init(&latchA, kButtonSettleMs);
487:  button_latch_init(&latchB, kButtonSettleMs);
488:  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);
489:
490:  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
491:    halt("PSRAM alloc failed");
492:  stamp.setBuffer(canvas.px, kSize, kSize, 16);
493:  namePatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
494:  size_t infoPixels = kQrSide * kQrSide > kSize * kPatchMaxH
495:                          ? kQrSide * kQrSide
496:                          : kSize * kPatchMaxH;
497:  infoPatch.saved = (uint16_t *)ps_malloc(infoPixels * sizeof(uint16_t));
498:  if (!namePatch.saved || !infoPatch.saved) halt("PSRAM alloc failed");
499:  buildQr();
500:  runner = runner_create(&canvas);
501:  if (!runner) halt("hack start failed");
502:  int first = start_pick_index(g_hacks, g_hack_count, kForcedStart, esp_random());
503:  if (kForcedStart && start_find_hack(g_hacks, g_hack_count, kForcedStart) < 0)
504:    Serial.printf("START_HACK \"%s\" not found, starting at random\n",
505:                  kForcedStart);
506:  if (runner_start(runner, first) != 0) halt("hack start failed");
507:  overlay_init(&overlay, kNameShownMs, qrPixels != nullptr);
508:  rotation_init(&rotation, kRotateMs, millis());
509:  hackStarted();
510:  printStats("boot");
511:  resetStats();
512:}
513:
514:void loop() {
515:  M5.update();
516:  if (!pollButtons()) pollRotation();
517:  pollTouch();
518:  pollBattery();
519:
520:  uint32_t t0 = micros();
521:  unsigned long delayUs = runner_step(runner);
522:  uint32_t t1 = micros();
523:  present();
524:  uint32_t t2 = micros();
525:  frames++;
526:  overlay_frame(&overlay, millis());
527:  stepUs += t1 - t0;
528:  pushUs += t2 - t1;
529:
530:  /* Only the push counts against the delay. A hack's delay is the pause after
531:   * it draws, so a hack that asks for a one-second hold must still get it
532:   * however long its own step took. */
533:  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
534:  uint32_t waitedUs = 0;
535:  bool switched = false;
536:  while (!switched && waitedUs < waitUsTarget) {
537:    uint32_t slice =
538:        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
539:    delayMicroseconds(slice);
540:    waitedUs += slice;
541:    M5.update();
542:    switched = pollButtons() || pollRotation();
543:    if (!switched) {
544:      pollTouch();
545:      pollBattery();
546:    }
547:    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
548:  }
549:  if (!switched) waitUs += micros() - t2;
550:
551:  if (millis() - statsAt >= kStatsEveryMs) {
552:    printStats("run");
553:#ifdef TE_DIAG
554:    teReport();
555:#endif
556:    resetStats();
557:  }
558:}

